const { x, y, z } = msg.payload;
let heading = null;
if (x !== null && y !== null) {
    heading = Math.atan2(y, x) * 180 / Math.PI;
    if (heading < 0) heading += 360;
}
const tiltWarn = z !== null && Math.abs(z) > 30e-6;
msg.payload = {
    heading: heading !== null ? heading.toFixed(1) : 'N/A',
    x_uT: x !== null ? (x * 1e6).toFixed(1) : 'overflow',
    y_uT: y !== null ? (y * 1e6).toFixed(1) : 'overflow',
    z_uT: z !== null ? (z * 1e6).toFixed(1) : 'overflow',
    tilt_warning: tiltWarn
};
return msg;
